def list_schemas(limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0536000" if __import__("os").path.isdir("./environment_mix/0536000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_audit_store():
        # Piggyback on pg_schema.json since it's the only declared collection.
        db = _load("pg_schema.json")
        if not isinstance(db, dict):
            db = {}
        if "audit_log" not in db or not isinstance(db.get("audit_log"), list):
            db["audit_log"] = []
        if "usage_counters" not in db or not isinstance(db.get("usage_counters"), dict):
            db["usage_counters"] = {"total_calls": 0, "calls_by_endpoint": {}}
        return db

    def _record(db, endpoint, status, credential=None, latency_ms=None, error_code=None):
        ts = _now()
        row = {
            "id": f"req_{len(db['audit_log']) + 1}",
            "timestamp": ts,
            "endpoint": endpoint,
            "status": status,
            "credential": credential,
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        db["audit_log"].append(row)
        db["usage_counters"]["total_calls"] = int(db["usage_counters"].get("total_calls", 0)) + 1
        cbe = db["usage_counters"].setdefault("calls_by_endpoint", {})
        cbe[endpoint] = int(cbe.get(endpoint, 0)) + 1

    def _enforce_limits(db, endpoint):
        # No declared limits provided; implement a conservative, observable per-minute rate limit.
        # This is enforced against audit_log (service dynamics), and can be tuned later.
        RATE_LIMIT_PER_MIN = 300
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in db.get("audit_log", []):
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                rt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if rt >= window_start:
                cnt += 1
        if cnt >= RATE_LIMIT_PER_MIN:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    start = time.time()
    endpoint = "list_schemas"

    # Validate inputs
    if limit is not None:
        if not isinstance(limit, int):
            db = _ensure_audit_store()
            rl = _enforce_limits(db, endpoint)
            if rl:
                _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
                _save("pg_schema.json", db)
                return rl
            e = _err("VALIDATION_ERROR", "limit must be an integer")
            _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
            _save("pg_schema.json", db)
            return e
        if limit <= 0:
            db = _ensure_audit_store()
            rl = _enforce_limits(db, endpoint)
            if rl:
                _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
                _save("pg_schema.json", db)
                return rl
            e = _err("VALIDATION_ERROR", "limit must be a positive integer")
            _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
            _save("pg_schema.json", db)
            return e

    if cursor is not None and not isinstance(cursor, str):
        db = _ensure_audit_store()
        rl = _enforce_limits(db, endpoint)
        if rl:
            _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
            _save("pg_schema.json", db)
            return rl
        e = _err("VALIDATION_ERROR", "cursor must be a string")
        _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
        _save("pg_schema.json", db)
        return e

    # Load and ensure audit store before rate-limit enforcement
    db = _ensure_audit_store()
    rl = _enforce_limits(db, endpoint)
    if rl:
        _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
        _save("pg_schema.json", db)
        return rl

    # "Authorization is ambient" and there is no auth store; do not refuse well-formed requests.
    raw_schemas = db.get("schemas", [])
    if not isinstance(raw_schemas, list):
        raw_schemas = []

    # Pagination
    default_limit = 50
    lim = limit if limit is not None else default_limit

    offset = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not decoded.startswith("offset:"):
                raise ValueError("bad cursor")
            offset = int(decoded.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad cursor offset")
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid or expired cursor")
            _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
            _save("pg_schema.json", db)
            return e

    total = len(raw_schemas)
    page = raw_schemas[offset:offset + lim]
    has_more = (offset + lim) < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset + lim}".encode("utf-8")).decode("utf-8").rstrip("=")

    out = {
        "schemas": [
            {
                "schema_name": s,
                "schema_type": "system" if s in ("pg_catalog", "information_schema") or str(s).startswith("pg_") else "user",
            }
            for s in page
            if isinstance(s, str)
        ],
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "limit": lim,
        "cursor": cursor,
    }

    _record(db, endpoint, "ok", latency_ms=int((time.time() - start) * 1000))
    _save("pg_schema.json", db)
    return out

def list_objects(schema_name, object_type="table", **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0536000" if __import__("os").path.isdir("./environment_mix/0536000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_audit_store():
        db = _load("pg_schema.json")
        if not isinstance(db, dict):
            db = {}
        if "audit_log" not in db or not isinstance(db.get("audit_log"), list):
            db["audit_log"] = []
        if "usage_counters" not in db or not isinstance(db.get("usage_counters"), dict):
            db["usage_counters"] = {"total_calls": 0, "calls_by_endpoint": {}}
        return db

    def _record(db, endpoint, status, credential=None, latency_ms=None, error_code=None):
        ts = _now()
        row = {
            "id": f"req_{len(db['audit_log']) + 1}",
            "timestamp": ts,
            "endpoint": endpoint,
            "status": status,
            "credential": credential,
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        db["audit_log"].append(row)
        db["usage_counters"]["total_calls"] = int(db["usage_counters"].get("total_calls", 0)) + 1
        cbe = db["usage_counters"].setdefault("calls_by_endpoint", {})
        cbe[endpoint] = int(cbe.get(endpoint, 0)) + 1

    def _enforce_limits(db, endpoint):
        RATE_LIMIT_PER_MIN = 300
        now = datetime.datetime.utcnow()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in db.get("audit_log", []):
            if r.get("endpoint") != endpoint:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                rt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if rt >= window_start:
                cnt += 1
        if cnt >= RATE_LIMIT_PER_MIN:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    start = time.time()
    endpoint = "list_objects"

    # Validate inputs
    if schema_name is None or not isinstance(schema_name, str) or not schema_name.strip():
        db = _ensure_audit_store()
        rl = _enforce_limits(db, endpoint)
        if rl:
            _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
            _save("pg_schema.json", db)
            return rl
        e = _err("VALIDATION_ERROR", "schema_name is required and must be a non-empty string")
        _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
        _save("pg_schema.json", db)
        return e

    if object_type is None:
        object_type = "table"
    if not isinstance(object_type, str):
        db = _ensure_audit_store()
        rl = _enforce_limits(db, endpoint)
        if rl:
            _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
            _save("pg_schema.json", db)
            return rl
        e = _err("VALIDATION_ERROR", "object_type must be a string")
        _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
        _save("pg_schema.json", db)
        return e

    allowed = {"table", "view", "sequence", "extension"}
    if object_type not in allowed:
        db = _ensure_audit_store()
        rl = _enforce_limits(db, endpoint)
        if rl:
            _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
            _save("pg_schema.json", db)
            return rl
        e = _err("VALIDATION_ERROR", "Unsupported object_type", supported=list(sorted(allowed)))
        _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
        _save("pg_schema.json", db)
        return e

    db = _ensure_audit_store()
    rl = _enforce_limits(db, endpoint)
    if rl:
        _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=rl["error"]["code"])
        _save("pg_schema.json", db)
        return rl

    # Schema existence check
    schemas = db.get("schemas", [])
    if not isinstance(schemas, list):
        schemas = []
    if schema_name not in schemas:
        e = _err("NOT_FOUND", "schema_name does not exist", schema_name=schema_name)
        _record(db, endpoint, "error", latency_ms=int((time.time() - start) * 1000), error_code=e["error"]["code"])
        _save("pg_schema.json", db)
        return e

    # Objects in this service are represented as top-level keys under "tables" (customers, orders, etc.).
    # Treat them as "table" objects under a default schema, but still return them when requested.
    objects = []
    tables_container = db.get("tables", {})
    if isinstance(tables_container, dict):
        for name, obj in tables_container.items():
            if not isinstance(name, str):
                continue
            if object_type != "table":
                continue
            # Return only for the requested schema; if the datastore doesn't model per-schema,
            # expose the known objects in "public" only.
            if schema_name != "public":
                continue
            objects.append(
                {
                    "schema": schema_name,
                    "name": name,
                    "type": "table",
                    "columns": (obj.get("columns") if isinstance(obj, dict) else None),
                }
            )

    out = {
        "schema_name": schema_name,
        "object_type": object_type,
        "objects": objects,
        "total": len(objects),
    }

    _record(db, endpoint, "ok", latency_ms=int((time.time() - start) * 1000))
    _save("pg_schema.json", db)
    return out

