def get_object_details(schema_name, object_name, object_type="table"):
    import json, os
    schema = json.load(open(os.path.join(_DB, "pg_schema.json"), encoding="utf-8"))
    tables = schema.get("tables", {}).get(schema_name, {})
    tdef = tables.get(object_name)
    if not tdef:
        if tables:
            object_name, tdef = next(iter(tables.items()))
        else:
            return {"error": f"object {schema_name}.{object_name} not found"}
    cols = []
    for c in tdef["columns"]:
        cols.append({
            "column": c["name"], "data_type": c.get("type", "text"),
            "is_primary_key": bool(c.get("pk")),
            "foreign_key": c.get("fk"),
            "nullable": not c.get("pk", False),
        })
    return {"schema": schema_name, "name": object_name, "type": object_type or "table",
            "columns": cols, "row_count": len(tdef.get("rows", []))}

