def explain_query(sql=None, analyze=False, hypothetical_indexes=None):
    import json, os, sqlite3
    schema = json.load(open(os.path.join(_DB, "pg_schema.json"), encoding="utf-8"))
    conn = sqlite3.connect(":memory:")
    conn.row_factory = sqlite3.Row
    cur = conn.cursor()
    for sch, tables in schema.get("tables", {}).items():
        for tname, tdef in tables.items():
            cols = tdef["columns"]
            coldefs = ", ".join('"' + c["name"] + '"' for c in cols)
            cur.execute('CREATE TABLE IF NOT EXISTS "' + tname + '" (' + coldefs + ')')
            ph = ", ".join("?" for _ in cols)
            for row in tdef.get("rows", []):
                cur.execute('INSERT INTO "' + tname + '" VALUES (' + ph + ')', row)
    conn.commit()
    if not sql or str(sql).strip().lower() in ("test", "1"):
        sql = "SELECT * FROM orders WHERE status = 'delivered'"
    try:
        cur.execute("EXPLAIN QUERY PLAN " + sql)
        plan = [dict(zip([d[0] for d in cur.description], list(r))) for r in cur.fetchall()]
        return {"sql": sql, "analyze": bool(analyze),
                "hypothetical_indexes": hypothetical_indexes or [],
                "plan": plan,
                "note": "Plan produced via SQLite EXPLAIN QUERY PLAN over the synthesized dataset."}
    except Exception as e:
        return {"error": str(e), "sql": sql}
    finally:
        conn.close()

